#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BK="$GSZ/routes/whatsapp.js.bak-step164-$TS"
echo "==> step164: owner-only bot commands (#6)"
cp "$GSZ/routes/whatsapp.js" "$BK"; echo "    backup: $BK"
restore(){ echo "!! error — restoring"; cp "$BK" "$GSZ/routes/whatsapp.js" 2>/dev/null || true; }
trap 'restore' ERR

echo "==> seeding owner number (editable later in admin)"
NODE_PATH="$GSZ/node_modules" node -e "
require('dotenv').config({path:'$GSZ/.env'});
const { Pool } = require('pg');
const p = new Pool({ host:process.env.DB_HOST, port:process.env.DB_PORT, database:process.env.DB_NAME, user:process.env.DB_USER, password:process.env.DB_PASS });
(async()=>{ try{
  await p.query(\"INSERT INTO wa_settings(key,value) VALUES('wa_owner_numbers','03193459191') ON CONFLICT (key) DO NOTHING\");
  const r = await p.query(\"SELECT value FROM wa_settings WHERE key='wa_owner_numbers'\");
  console.log('    owner numbers = ' + (r.rows[0] ? r.rows[0].value : '(none)'));
  await p.end();
}catch(e){ console.error('    seed failed: '+e.message); process.exit(1); } })();
"

PATCHER=$(mktemp /tmp/patch_step164.XXXXXX.js)
echo "" | base64 -d > "$PATCHER"
echo "==> applying"
NODE_PATH="$GSZ/node_modules" node "$PATCHER" "$GSZ"
echo "==> validating"
node --check "$GSZ/routes/whatsapp.js" && echo "    node --check ok"
echo "==> restarting"
pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000
for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    homepage $CODE after ${i}s"; false; }
echo "    homepage 200: OK (after ${i}s)"
rm -f "$PATCHER"
trap - ERR
echo ""
echo "==> step164 OK  From your owner WhatsApp (03193459191), message the verification bot: help · stock · stock <name> · orders · order <no> · addstock <planId> then one unit per line. Only owner numbers work. (Dashboard field to edit the owner list comes next.)"
